def score(
    labels: FightLabels,
    preds: Predictions,
    tolerance_secs: float = DEFAULT_TOLERANCE_SECS,
    strict_fighter: bool = False,
) -> Report:
    if labels.fps != preds.fps:
        print(f"  warning: label fps ({labels.fps}) != pipeline fps ({preds.fps}); "
              f"using label fps for all conversions")
    return Report(
        video=labels.video,
        fps=labels.fps,
        scored_minutes=len(labels.scored_frames()) / labels.fps / 60,
        strikes=score_strikes(labels, preds, tolerance_secs, strict_fighter),
        state=score_state(labels, preds),
        rounds=score_rounds(labels, preds),
    )


# ---------------------------------------------------------------------------
# Rendering
# ---------------------------------------------------------------------------

def _pct(v: Optional[float]) -> str:
    return f"{v:6.1%}" if v is not None else "     —"
--- build_labels ---
def build_labels(video: str) -> FightLabels:
    db = SessionLocal()
    try:
        fight_id, video_path, fps, _ = lookup_fight(db, video)

        row = db.execute(
            text("SELECT labeled_at FROM fights WHERE id = :fid"), {"fid": fight_id}
        ).first()
        if row is None or row.labeled_at is None:
            raise NotLabeled(
                f"{video_path} has no labeled_at yet — finish labeling in the "
                f"UI first (POST /fights/{fight_id}/finish-labeling)"

